import CopilotStartHeader from './components/CopilotStartHeader/CopilotStartHeader'
import CopilotGreetingHeader from './components/CopilotGreetingHeader/CopilotGreetingHeader'

export interface DashboardHeaderProps {
  showStartHeader: boolean
  username: string
}

export function DashboardHeader({showStartHeader, username}: DashboardHeaderProps) {
  if (showStartHeader) {
    return <CopilotStartHeader />
  }

  return <CopilotGreetingHeader username={username} />
}
