import {CopilotAnimation, CopilotAnimationType} from '@github-ui/copilot-animation'
import {Heading, Stack} from '@primer/react'

export interface CopilotGreetingHeaderProps {
  username: string
  animationType?: CopilotAnimationType
  loopAnimation?: boolean
}

export default function CopilotGreetingHeader({
  username,
  animationType = 'static',
  loopAnimation = false,
}: CopilotGreetingHeaderProps) {
  return (
    <Stack direction="horizontal" align="center" gap="condensed">
      <CopilotAnimation animationType={animationType} loopAnimation={loopAnimation} size={48} />
      <Heading as="h2">Hi @{username}, how can I help?</Heading>
    </Stack>
  )
}
